    "pcfut": {
      "id": "pcfut",
      "name": "Present Continuous for the future",
      "form": "I'm working tomorrow",
      "tone": "future",
      "kind": "Future form",
      "formula": "am / is / are + V-ing + a future time",
      "affirmative": "I'm meeting Anna tomorrow.",
      "negative": "I'm not meeting Anna tomorrow.",
      "question": "Are you meeting Anna tomorrow?",
      "note": "",
      "usage": {
        "en": "An arrangement for the future, often with a time named. The form is Present Continuous. The meaning is future.",
        "ru": "Договоренность на будущее, время часто названо. Форма — Present Continuous. Значение — будущее."
      },
      "cases": [
        "a diary arrangement",
        "a plan with another person"
      ],
      "signals": [
        "tomorrow",
        "next week",
        "on Friday"
      ],
      "mistakes": {
        "en": "A personal intention without an arrangement is closer to be going to.",
        "ru": "Личное намерение без договоренности ближе к be going to."
      },
      "differs": {
        "en": "be going to can be only an intention. Present Continuous for the future usually means it is arranged.",
        "ru": "be going to может быть только намерением. Present Continuous для будущего обычно значит, что это уже договорено."
      },
      "links": [
        [
          "Cambridge Grammar",
          "https://dictionary.cambridge.org/grammar/british-grammar/future-"
        ]
      ],
      "examples": [
        {
          "en": "I am taking the train to Paris tomorrow.",
          "ru": "Завтра я еду поездом в Париж.",
          "source": "Cambridge Grammar",
          "url": "https://dictionary.cambridge.org/grammar/british-grammar/future-"
        },
        {
          "en": "The band is visiting Denmark next May.",
          "ru": "Группа едет в Данию в следующем мае.",
          "source": "Cambridge Grammar",
          "url": "https://dictionary.cambridge.org/grammar/british-grammar/future-"
        }
      ],
      "related": [
        "pc",
        "going",
        "psfut"
      ],
      "bank": "pcfut"
    },
