    "backshift": {
      "id": "backshift",
      "name": "Backshift",
      "form": "Present becomes Past",
      "tone": "advanced",
      "kind": "Reported speech",
      "formula": "Present → Past, Past → Past Perfect, will → would, can → could, may → might",
      "affirmative": "am/is → was, have seen → had seen, will → would",
      "negative": "",
      "question": "",
      "note": "",
      "usage": {
        "en": "When the reporting verb is past, the quoted tense usually moves one step back. Time and place words move too: today → that day, tomorrow → the next day, yesterday → the day before, this → that, here → there.",
        "ru": "Если глагол сообщения в прошлом, время цитаты обычно сдвигается на шаг назад. Слова времени и места тоже: today → that day, tomorrow → the next day, yesterday → the day before, this → that, here → there."
      },
      "cases": [
        "present to past",
        "past to past perfect",
        "will to would",
        "can to could",
        "may to might",
        "today to that day",
        "tomorrow to the next day",
        "yesterday to the day before"
      ],
      "signals": [
        "that day",
        "the next day",
        "the day before"
      ],
      "mistakes": {
        "en": "If the fact is still true, the present can stay. The backshift is the usual reported pattern, not a new tense.",
        "ru": "Если факт все еще верен, настоящее может остаться. Сдвиг — обычный образец косвенной речи, не новое время."
      },
      "differs": {
        "en": "Direct speech keeps the original tense. Reported speech moves it when the reporting verb is past.",
        "ru": "Прямая речь сохраняет исходное время. Косвенная речь сдвигает его, если глагол сообщения в прошлом."
      },
      "links": [
        [
          "Cambridge Grammar",
          "https://dictionary.cambridge.org/grammar/british-grammar/indirect-speech"
        ]
      ],
      "examples": [
        {
          "en": "I told them ( that ) I was tired",
          "ru": "",
          "source": "Cambridge Grammar",
          "url": "https://dictionary.cambridge.org/grammar/british-grammar/indirect-speech"
        },
        {
          "en": "I told my wife I didn’t want a party on my 50th birthday",
          "ru": "",
          "source": "Cambridge Grammar",
          "url": "https://dictionary.cambridge.org/grammar/british-grammar/indirect-speech"
        }
      ],
      "related": [
        "rep_state"
      ],
      "bank": ""
    },
